"""«Otras voces» por hito: síntesis (no citas) de comentaristas, con su ficha APA en datos.py (refs)."""
COM = {
 "esteban": [["Agustín", "Sostiene que la oración de Esteban por sus verdugos fue escuchada en la conversión del joven que guardaba los mantos: sin ella la Iglesia no tendría a Pablo ([[ref:agustin_esteban|Sermón 315]])."],
             ["Matthew Henry", "Observa que Lucas presenta a Saulo como «joven» para subrayar lo temprano de su celo y lo largo de su servicio posterior; el que consintió en una muerte sería después perseguido por la misma causa ([[ref:henry|Comentario]])."]],
 "damasco": [["N. T. Wright", "Lee la escena no como el paso de una religión a otra, sino como el momento en que un judío celoso descubre que el Mesías crucificado es el Señor de Israel, y que su celo debía volverse misión a las naciones ([[ref:wright|Pablo: una biografía]])."],
             ["J. MacArthur", "Subraya la soberanía de la gracia: Pablo no buscaba a Cristo; Cristo lo buscó a él, y la pregunta «¿por qué me persigues?» enseña la unión del Señor con su iglesia ([[ref:macarthur|Biblia de estudio]])."],
             ["Jamieson, Fausset y Brown", "Notan que las tres narraciones de Hechos (9, 22, 26) difieren en detalles menores —si los acompañantes oyeron la voz o vieron la luz— como testimonios independientes de un mismo hecho ([[ref:jfb|Comentario]])."]],
 "arabia": [["Hengel y Schwemer", "Proponen que «Arabia» fue una misión real en las ciudades nabateas y no un retiro contemplativo; la persecución del etnarca de Aretas sería su consecuencia ([[ref:hengel|Pablo entre Damasco y Antioquía]])."],
            ["Murphy-O'Connor", "Ve en el regreso a Damasco el signo de una misión fallida entre los nabateos, enemigos de los judíos, que obligó a Pablo a replantear su método ([[ref:murphy|Pablo: una vida crítica]])."]],
 "antioquia": [["Hengel y Schwemer", "Hacen de Antioquía el lugar donde la teología de Pablo se hizo práctica: una comunidad de judíos y griegos sin ley ritual, de la que Bernabé fue el verdadero fundador ([[ref:hengel|Pablo entre Damasco y Antioquía]])."],
               ["Matthew Henry", "Comenta que el nombre «cristianos» pudo nacer como burla, pero que los discípulos lo hicieron suyo porque confesaba de quién eran ([[ref:henry|Comentario]])."]],
 "envio": [["Calvino", "Enseña que el llamado interior del Espíritu fue confirmado por la iglesia con ayuno, oración e imposición de manos: nadie se envía a sí mismo ([[ref:calvino_hch|Comentario a Hechos]])."],
           ["F. F. Bruce", "Señala que Antioquía fue la primera iglesia que entendió la misión como tarea propia, enviando a sus dos mejores maestros ([[ref:bruce|Pablo, apóstol del corazón liberado]])."]],
 "chipre": [["W. M. Ramsay", "Explica el cambio de Saulo a Pablo como el uso del nombre romano al tratar con un procónsul; nada en el texto indica que fuera un homenaje a Sergio Paulo ([[ref:ramsay|San Pablo el viajero]])."],
            ["S. Mitchell", "Relaciona a los Sergii Pauli con fincas cerca de Antioquía de Pisidia, lo que explicaría por qué Pablo subió allí desde Perge ([[ref:mitchell|Anatolia]])."]],
 "listra": [["Jamieson, Fausset y Brown", "Observan la rapidez con que la misma multitud pasó de adorar a apedrear, y que Pablo se levantó al día siguiente para seguir a Derbe: la lapidación de 2 Co 11:25 es ésta ([[ref:jfb|Comentario]])."],
            ["W. M. Calder", "Publicó las dedicatorias a Zeus y Hermes halladas cerca de Listra, que confirman el culto conjunto de ambos dioses en Licaonia ([[ref:calder|Zeus y Hermes en Listra]])."]],
 "galatas": [["Lutero", "Lee Gálatas como la carta de la libertad cristiana: la justicia no viene de la ley sino de Cristo recibido por la fe; cualquier añadido vacía la cruz ([[ref:lutero_ga|Comentario a Gálatas]])."],
             ["J. D. G. Dunn", "Entiende «obras de la ley» sobre todo como las marcas de identidad judía —circuncisión, comidas, sábado— que separaban a Israel de las naciones; la justificación por la fe abre la mesa a todos ([[ref:dunn|La teología del apóstol Pablo]])."],
             ["F. F. Bruce", "Defiende que la carta se dirigió a las iglesias del sur de Galacia poco antes del concilio, lo que explica que no cite su decreto ([[ref:bruce|Pablo, apóstol del corazón liberado]])."]],
 "concilio": [["Calvino", "Destaca que la decisión no se tomó por votación sino por la Palabra —la cita de Amós— y por los hechos de Dios entre los gentiles ([[ref:calvino_hch|Comentario a Hechos]])."],
              ["C. S. Keener", "Lee las cuatro abstenciones a la luz de Lv 17–18, las normas para el extranjero que vive en medio de Israel: no salvan, hacen posible la convivencia ([[ref:keener|Hechos: comentario exegético]])."]],
 "antioquia2": [["Agustín", "Sostuvo contra Jerónimo que la reprensión fue real y pública, porque Pedro erró de verdad y Pablo no mentiría; la Escritura no admite mentiras útiles ([[ref:agustin_jer|Cartas]])."],
                ["Crisóstomo", "Pensó que Pedro y Pablo representaron la escena de acuerdo para corregir a los judaizantes sin humillar a Pedro ([[ref:crisostomo_hch|Homilías sobre Hechos]])."]],
 "filipos": [["Matthew Henry", "Ve en Lidia, la esclava y el carcelero tres conversiones distintas —una religiosa, una poseída, un pagano rudo— que muestran que el evangelio es para todos ([[ref:henry|Comentario]])."],
             ["A. N. Sherwin-White", "Muestra que la escena de los magistrados que se asustan al saber que azotaron a ciudadanos romanos corresponde exactamente al derecho del s. I ([[ref:sherwin|Derecho romano en Hechos]])."]],
 "atenas": [["Crisóstomo", "Admira que Pablo no citara la Escritura, que los atenienses no conocían, sino sus poetas, y que partiera del altar al dios desconocido: se hizo griego con los griegos ([[ref:crisostomo_hch|Homilías sobre Hechos]])."],
            ["J. MacArthur", "Recuerda que el discurso no termina en filosofía sino en arrepentimiento, juicio y resurrección, y que por eso unos se burlaron y otros creyeron ([[ref:macarthur|Biblia de estudio]])."]],
 "galion": [["R. Riesner", "Hace de la inscripción de Delfos el ancla de toda la cronología: con Galión en 51–52, Pablo llegó a Corinto a comienzos de 50 y partió en 52 ([[ref:riesner|Los primeros años de Pablo]])."],
            ["A. N. Sherwin-White", "Interpreta la negativa de Galión como un precedente: un gobernador romano se niega a considerar delito la predicación cristiana ([[ref:sherwin|Derecho romano en Hechos]])."]],
 "romanos": [["Lutero", "Llama a Romanos «el evangelio más puro» y pide aprenderla de memoria: en ella está todo lo que el cristiano debe saber ([[ref:lutero_ro|Prefacio a Romanos]])."],
             ["J. D. G. Dunn", "Toma Romanos como el esquema de la teología de Pablo: de la ira de Dios a la justificación, del Espíritu a Israel y a la vida en el cuerpo de Cristo ([[ref:dunn|La teología del apóstol Pablo]])."],
             ["D. W. J. Gill", "Discute si el Erasto de la losa de Corinto es el de Ro 16:23: el nombre y la fecha coinciden; el cargo de edil no es exactamente «tesorero» ([[ref:gill|Erasto el edil]])."]],
 "mileto": [["Matthew Henry", "Lee el discurso como un espejo del pastor: lágrimas, trabajo con las manos, enseñanza pública y en las casas, y un corazón desprendido de la propia vida ([[ref:henry|Comentario]])."],
            ["Jamieson, Fausset y Brown", "Notan que los «ancianos» (presbíteros) son llamados en el mismo discurso «obispos» (episcopos): un solo oficio con dos nombres ([[ref:jfb|Comentario]])."]],
 "templo": [["Josefo", "Describe la balaustrada del templo con inscripciones en griego y latín que prohibían el paso a los extranjeros bajo pena de muerte ([[ref:josefo_guerra5|Guerra V]])."],
            ["C. S. Keener", "Observa que los romanos permitían a los judíos ejecutar a los extranjeros que violaran el recinto, incluso ciudadanos romanos: la acusación era mortal ([[ref:keener|Hechos: comentario exegético]])."]],
 "festo": [["A. N. Sherwin-White", "Muestra que la apelación al César era un derecho real del ciudadano en el s. I, y que Festo no podía negarla ([[ref:sherwin|Derecho romano en Hechos]])."],
           ["J. MacArthur", "Ve en la apelación el cumplimiento de Hch 23:11: Dios usa el derecho romano para llevar a su apóstol a Roma ([[ref:macarthur|Biblia de estudio]])."]],
 "tempestad": [["James Smith", "Calculó, con la deriva de una nave a la capa bajo el euroaquilón, que desde Cauda se llega a Malta en trece días: la cifra de Lucas ([[ref:smith|El viaje y naufragio de San Pablo]])."],
               ["Matthew Henry", "Comenta que Pablo, el preso, se vuelve el verdadero capitán: anima, parte el pan y es la causa de que se salven todos ([[ref:henry|Comentario]])."]],
 "cautividad": [["F. F. Bruce", "Defiende la procedencia romana de las cuatro cartas y la liberación posterior de Pablo, en línea con Eusebio ([[ref:bruce|Pablo, apóstol del corazón liberado]])."],
                ["N. T. Wright", "Prefiere Éfeso como lugar de las cartas de la cautividad, por la cercanía con Colosas y Filipos y por la «sentencia de muerte» de 2 Co 1:8 ([[ref:wright|Pablo: una biografía]])."]],
 "martirio": [["Eusebio", "Transmite la tradición de la absolución tras la primera defensa, el nuevo ministerio y la muerte por la espada bajo Nerón, con los «trofeos» de Pedro y Pablo en Roma ([[ref:eusebio|Historia eclesiástica]])."],
              ["Tertuliano", "Dice que en Roma Pablo «fue coronado con la muerte de Juan», es decir, decapitado, como correspondía a un ciudadano ([[ref:tertuliano|Prescripción 36]])."]],
 "legado": [["E. P. Sanders", "Recuerda que el judaísmo de Pablo era una religión de gracia y pacto, no de méritos; lo que Pablo criticó fue la ley como frontera, no como camino de salvación por obras ([[ref:sanders|Pablo y el judaísmo palestino]])."],
            ["N. T. Wright", "Concluye que Pablo fue el primer teólogo cristiano: quien pensó, en cartas urgentes, lo que significa que el Mesías de Israel sea el Señor del mundo ([[ref:wright|Pablo: una biografía]])."]],
}
